mapper.delete:
	DELETE  /* SQL_ID: RdfMappingRuleMapper.deleteRdfMappingRuleByRdfModelId */
    FROM dtmeta.tb_rdf_mappingrule
    WHERE rdf_mappg_model_id = #{rdfMappgModelId}

mapper.select:
SELECT /* SQL_ID: RdfMappingRuleMapper.selectRdfNamespaceListByRdfModelId */ p2.rdf_nmsp_id , p2.rdf_nmsp_pfix , p2.rdf_nmsp_uri FROM dtmeta.tb_rdf_mappingrule t1 INNER JOIN dtmeta.tb_rdf_property p1 ON t1.rdf_prpty_id = p1.rdf_prpty_id INNER JOIN dtmeta.tb_rdf_namespace p2 ON p1.rdf_nmsp_id = p2.rdf_nmsp_id WHERE 1=1
AND t1.rdf_mappg_model_id = #{rdfMappgModelId}
UNION SELECT c2.rdf_nmsp_id , c2.rdf_nmsp_pfix , c2.rdf_nmsp_uri FROM dtmeta.tb_rdf_mappingrule t1 INNER JOIN dtmeta.tb_rdf_class c1 ON t1.objt_rdf_class_id = c1.rdf_class_id INNER JOIN dtmeta.tb_rdf_namespace c2 ON c1.rdf_nmsp_id = c2.rdf_nmsp_id WHERE 1=1
AND t1.rdf_mappg_model_id = #{rdfMappgModelId}
UNION SELECT n1.rdf_nmsp_id , n1.rdf_nmsp_pfix , n1.rdf_nmsp_uri FROM dtmeta.tb_rdf_namespace n1 WHERE n1.rdf_nmsp_uri IN #{item}
ORDER BY rdf_nmsp_pfix

mapper.update:
		UPDATE /* SQL_ID: RdfMappingRuleMapper.updateRdfMappingrule */
       		dtmeta.tb_rdf_mappingrule
	   	SET  		
			objt_data_mappg_yn = #{objtDataMappgYn}

				, rdf_mappg_rule_odrg = #{rdfMappgRuleOdrg}


				, objt_rdf_class_id = #{objtRdfClassId}



					, objt_prpty_id = null



						, objt_prpty_id = #{objtPrptyId}




				, objt_literal_yn = #{objtLiteralYn}


				, objt_rdf_mappg_id = #{objtRdfMappgId}

	 	WHERE 
		 	rdf_mappg_rule_id = #{rdfMappgRuleId}

mapper.select:
SELECT t1.*  /* SQL_ID: RdfMappingRuleMapper.selectRdfMappingRule */
FROM dtmeta.tb_rdf_mappingrule          t1
WHERE rdf_mappg_rule_id = #{rdfMappgRuleId}
